/**
 * Capture a session's pi ENTRIES as JSON, for use as a test fixture.
 *
 * The conformance corpus under `contracts/conformance/` is generated by the
 * Swift app; this client's fold is additionally checked against a scripted
 * double (`scripts/fake-machine.ts`) whose shape I wrote by reading the
 * extension. Both can be wrong in the same way. A dump from a REAL pi session
 * is the only thing that checks my fold against what the machine actually
 * sends — which is how the double's own lies got found (timestamps inside
 * `message`, an entry that was never written).
 *
 *   npx tsx scripts/dump-entries.ts \
 *     --relay http://m5max.tail5f1ece.ts.net:3000 \
 *     --pair  'unbien://pair?t=…&epk=…&n=…&rm=…' \
 *     --out   /tmp/unbien-fixture.json
 *
 * (`npx tsx`, not `node --experimental-strip-types`: this package writes
 * extensionless-`.js` specifiers for the browser's sake, and Node's type
 * stripping will not resolve them to `.ts`.)
 *
 * Honest limits:
 *  - This process has NO stored device identity (Node has no localStorage), so
 *    every run is a NEW device and needs a FRESH pairing code. That is the
 *    protocol working, not a bug: the machine's code is single-use.
 *  - Whatever the session's rows contain gets written to disk verbatim — prompt
 *    text, tool output, file paths. Treat the output file as containing your
 *    session; keep it out of the repo (`/tmp` by default is deliberate).
 */
import { mkdirSync, writeFileSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { deviceIdentity } from "../src/identity.js"
import { parseInvite } from "../src/invite.js"
import { SessionClient, type RelayRoomList } from "../src/session-client.js"

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`)
  return i >= 0 ? process.argv[i + 1] : undefined
}

function flag(name: string): boolean {
  return process.argv.includes(`--${name}`)
}

function describeRooms(epk: string, rooms: RelayRoomList): string {
  if (rooms.status !== "ok") return `rooms_check: ${rooms.status}`
  return rooms.rooms
    .map(
      (room) =>
        `  ${room.room_id}${room.name ? ` — ${room.name}` : ""}${
          room.cwd ? ` (${room.cwd})` : ""
        }${room.parent ? " [subagent]" : ""}`,
    )
    .join("\n")
}

async function main(): Promise<number> {
  const relay = arg("relay")
  const pairCode = arg("pair")
  if (!relay || !pairCode) {
    console.error(
      "usage: dump-entries --relay http://host:3000 --pair unbien://pair?… " +
        "[--room <id>] [--out <path>] [--max-pages N] [--include-panels]",
    )
    return 2
  }
  const out = resolve(arg("out") ?? "/tmp/unbien-fixture.json")
  const maxPages = Number(arg("max-pages") ?? 200)

  const invite = parseInvite(pairCode)
  const client = new SessionClient(relay, deviceIdentity(), {
    onRelayIdentity: (pubkey) => console.log(`relay identity: ${pubkey}`),
  })

  console.log(`connecting to ${relay} …`)
  await client.connect()

  console.log(`pairing as a one-off device (${invite.epk.slice(0, 8)}…) …`)
  const verdict = await client.pairAwaited(invite, "web-client fixture dump")
  if (!verdict.ok) {
    console.error(
      `pairing refused: ${verdict.detail} — the code is single-use, run ` +
        "/unbien pair again",
    )
    client.close()
    return 1
  }

  const rooms = await client.listRooms(invite.epk)
  console.log(describeRooms(invite.epk, rooms))
  if (rooms.status !== "ok") {
    console.error(`cannot list rooms: ${rooms.status}`)
    client.close()
    return 1
  }

  const wanted = arg("room") ?? invite.roomId
  const room = rooms.rooms.find((candidate) => candidate.room_id === wanted)
  if (!room) {
    console.error(
      `room ${wanted} is not in this machine's list — pass --room <id> from the list above`,
    )
    client.close()
    return 1
  }

  client.setRoutingPeer(invite.epk)
  client.setRoom(room.room_id)
  // The first frame to a trusted peer is what triggers the extension's attach.
  client.requestSync()

  const { entries, leafId } = await client.getEntries(undefined, maxPages)
  console.log(`walked ${entries.length} entries (leaf ${leafId ?? "none"})`)

  const state = await client
    .request<Record<string, unknown>>("get_state")
    .catch(() => undefined)

  const fixture = {
    fetchedAt: new Date().toISOString(),
    relay,
    peer: invite.epk,
    room: {
      roomId: room.room_id,
      name: room.name,
      cwd: room.cwd,
      caps: room.caps,
      parent: room.parent,
    },
    // The machine's caps matter for reading a fixture later: a machine without
    // `images` never sent image blocks, so their absence proves nothing.
    machine: verdict.machine,
    state,
    leafId,
    entries,
  }

  if (flag("include-panels")) {
    // Panels ride `session_sync` notifications rather than `get_entries`, so a
    // fixture without them cannot test the subagent/plan/ask fold.
    const panels: unknown[] = []
    client.on("envelope", (env) => {
      const rpc = env.rpc as Record<string, unknown> | undefined
      if (rpc && typeof rpc.type === "string") panels.push(rpc)
    })
    client.requestSync()
    await new Promise((r) => setTimeout(r, 2500))
    Reflect.set(fixture, "panels", panels)
    console.log(`captured ${panels.length} panel frames`)
  }

  mkdirSync(dirname(out), { recursive: true })
  writeFileSync(out, JSON.stringify(fixture, null, 2))
  console.log(
    `wrote ${out} (${(JSON.stringify(fixture).length / 1024) | 0} KB)`,
  )
  client.close()
  return entries.length > 0 ? 0 : 1
}

main()
  .then((code) => process.exit(code))
  .catch((err) => {
    console.error(err instanceof Error ? `${err.name}: ${err.message}` : err)
    process.exit(1)
  })
